// 动态版：把 MOTION 插进 SCENE 的 <style> 里
export const MOTION = `@keyframes rp{0%{rx:24px;ry:4px;opacity:0}12%{opacity:1}100%{rx:300px;ry:51px;opacity:0}}.rp ellipse{stroke-opacity:.55;animation:rp 8s steps(120) infinite}.rp ellipse:nth-child(2){animation-delay:-1.6s}.rp ellipse:nth-child(3){animation-delay:-3.2s}.rp ellipse:nth-child(4){animation-delay:-4.8s}.rp ellipse:nth-child(5){animation-delay:-6.4s}@keyframes bob{50%{translate:0 -2.5px}}.fw{animation:bob 8s steps(120) infinite}@keyframes br{50%{opacity:.6}}.wl{animation:br 20s steps(300) infinite}@keyframes dr{0%{translate:0 0;opacity:0}12%,85%{opacity:1}100%{translate:150px -24px;opacity:0}}.pe use{animation:dr 22s steps(330) infinite}.pe use:nth-child(2){animation-delay:-4.4s}.pe use:nth-child(3){animation-delay:-8.8s}.pe use:nth-child(4){animation-delay:-13.2s}.pe use:nth-child(5){animation-delay:-17.6s}@keyframes du{0%{translate:0 0;opacity:0}30%,70%{opacity:1}100%{translate:18px -70px;opacity:0}}.du circle{animation:du 14s steps(210) infinite}.du circle:nth-child(2){animation-delay:-2.8s}.du circle:nth-child(3){animation-delay:-5.6s}.du circle:nth-child(4){animation-delay:-8.4s}.du circle:nth-child(5){animation-delay:-11.2s}@media (prefers-reduced-motion:reduce){*{animation:none!important}}`
